CREATE TABLE projects (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE runs (project_id TEXT NOT NULL REFERENCES projects(id), id TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), data TEXT NOT NULL, PRIMARY KEY(project_id,id));
CREATE UNIQUE INDEX one_active_run ON runs(active) WHERE active=1;
CREATE TABLE tasks (project_id TEXT NOT NULL REFERENCES projects(id), id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE dependencies (project_id TEXT NOT NULL, task_id TEXT NOT NULL, dependency_id TEXT NOT NULL, PRIMARY KEY(project_id,task_id,dependency_id), CHECK(task_id != dependency_id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,dependency_id) REFERENCES tasks(project_id,id));
CREATE TABLE run_tasks (project_id TEXT NOT NULL, run_id TEXT NOT NULL, task_id TEXT NOT NULL, PRIMARY KEY(project_id,run_id,task_id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id));
CREATE TABLE decisions (project_id TEXT NOT NULL REFERENCES projects(id), id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE agents (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id));
CREATE TABLE invocations (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, snapshot_id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id,snapshot_id) REFERENCES agents(project_id,run_id,id));
CREATE TABLE attempts (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, task_id TEXT NOT NULL, number INTEGER NOT NULL CHECK(number > 0), data TEXT NOT NULL, UNIQUE(project_id,run_id,task_id,number), PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id,task_id) REFERENCES run_tasks(project_id,run_id,task_id));
CREATE TABLE submissions (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, attempt_id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id,attempt_id) REFERENCES attempts(project_id,run_id,id));
CREATE TABLE reviews (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, submission_id TEXT NOT NULL, task_id TEXT NOT NULL, number INTEGER NOT NULL CHECK(number > 0), data TEXT NOT NULL, UNIQUE(project_id,run_id,task_id,number), FOREIGN KEY(project_id,run_id,task_id) REFERENCES run_tasks(project_id,run_id,task_id), PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id,submission_id) REFERENCES submissions(project_id,run_id,id));
CREATE TABLE llm_calls (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL UNIQUE, invocation_id TEXT NOT NULL, agent_id TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, provider_request_id TEXT, attempt INTEGER NOT NULL CHECK(attempt > 0), purpose TEXT NOT NULL, status TEXT NOT NULL, input_tokens INTEGER, cached_tokens INTEGER, uncached_tokens INTEGER, output_tokens INTEGER, total_tokens INTEGER, usage_provenance TEXT NOT NULL, usage_completeness TEXT NOT NULL, price_snapshot TEXT, estimated_cost TEXT, error_type TEXT, error_message TEXT, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id,invocation_id) REFERENCES invocations(project_id,run_id,id));
CREATE TABLE command_results (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id));
CREATE TABLE artifacts (hash TEXT PRIMARY KEY, path TEXT NOT NULL, size INTEGER NOT NULL);
CREATE TABLE tool_records (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id));
CREATE TABLE interventions (project_id TEXT NOT NULL, run_id TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,run_id,id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id));
CREATE TABLE events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), run_id TEXT, task_id TEXT, type TEXT NOT NULL, actor TEXT NOT NULL, schema_version INTEGER NOT NULL, payload TEXT NOT NULL, timestamp TEXT NOT NULL, data TEXT NOT NULL, FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id));
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TABLE artifact_metadata (project_id TEXT NOT NULL, run_id TEXT NOT NULL, submission_id TEXT NOT NULL, path TEXT NOT NULL, content_hash TEXT NOT NULL, before_hash TEXT, PRIMARY KEY(project_id,run_id,submission_id,path), FOREIGN KEY(project_id,run_id,submission_id) REFERENCES submissions(project_id,run_id,id));
